[
  {
    "statement": "Studies have examined several actions to mitigate the impacts of roads on amphibian populations.",
    "citations": []
  },
  {
    "statement": "Two studies in Germany found that closing roads during seasonal amphibian migration protected large numbers of amphibians from death.",
    "citations": [
      "842"
    ]
  },
  {
    "statement": "Studies in several countries, including Canada, Germany, and the USA, showed that installing culverts or tunnels significantly reduced amphibian road deaths.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "One study found that installing culverts or tunnels was only effective at reducing amphibian road deaths when barrier fencing was also installed.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Multiple studies found that 23-100% of culverts or tunnels were used by amphibians.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "The effectiveness and use of amphibian crossings can be influenced by their design, including diameter, length, lighting, and substrate.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Some culvert designs, such as those with one-way tunnels and vertical entry chutes, were found to be unsuitable and resulted in high mortality rates for amphibians.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "One study noted that despite the installation of culverts, thousands of amphibians were still killed on the road.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Human assistance for migrating amphibians has been studied.",
    "citations": []
  },
  {
    "statement": "Despite efforts to move large numbers of amphibians across roads, two studies in Italy and the UK observed population declines of 64-70% over 6-10 years in assisted toad populations.",
    "citations": [
      "784"
    ]
  },
  {
    "statement": "In the UK, one study found that over 500 toads were still killed on roads at 7% of sites that had human assistance patrols.",
    "citations": [
      "784"
    ]
  }
]

[
  {
    "statement": "A meta-analysis of 24 studies in North America indicated that partial harvesting resulted in smaller reductions in salamander populations compared to clearcutting.",
    "citations": [
      "844",
      "851",
      "852"
    ]
  },
  {
    "statement": "Partial harvesting encompasses methods like harvesting groups of trees, shelterwood harvesting, and thinning.",
    "citations": [
      "844",
      "851",
      "852"
    ]
  },
  {
    "statement": "When compared to clearcutting, three studies in the USA on harvesting trees in small groups did not find a higher abundance of amphibians or salamanders.",
    "citations": [
      "844"
    ]
  },
  {
    "statement": "Three studies in the USA found that shelterwood harvesting led to higher, similar, or initially higher and then similar salamander abundance in comparison to clearcutting.",
    "citations": [
      "851"
    ]
  },
  {
    "statement": "In the case of thinning, two of four studies in the USA discovered higher amphibian abundance or a less negative overall response in thinned forests compared to clearcut forests.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "The other two of four studies in the USA on thinning had mixed results for amphibian abundance depending on the species and time since harvest.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "One study found that emigrating salamanders used thinned forests significantly more than the salamanders used clearcuts.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "In contrast to unharvested areas, two US studies found that harvesting trees in small groups significantly decreased salamander abundance.",
    "citations": [
      "844"
    ]
  },
  {
    "statement": "In contrast to unharvested areas, two US studies found that harvesting trees in small groups altered salamander species composition.",
    "citations": [
      "844"
    ]
  },
  {
    "statement": "Two out of three US studies showed that shelterwood harvesting decreased salamander abundance when compared to areas with no harvesting.",
    "citations": [
      "851"
    ]
  },
  {
    "statement": "Two out of three US studies showed that shelterwood harvesting changed the composition of salamander species when compared to areas with no harvesting.",
    "citations": [
      "851"
    ]
  },
  {
    "statement": "Studies on thinning compared to unharvested forests have shown mixed effects on salamander populations.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "When comparing thinned to unharvested forests, the abundance of some salamander species increased while the abundance of others, like the ensatina salamanders, decreased.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "One study noted a negative overall response of amphibians to forest thinning.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "One study found that a high volume of pre-existing downed wood helped prevent amphibian population declines after forest thinning.",
    "citations": [
      "852"
    ]
  }
]

